contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Drive the contract and assert the owner-only withdrawal property.
    // params:
    // - sender: the address used to call withdrawAll (simulated via address(this) and tx origin constraints not available),
    // - recipient: address to receive funds from c,
    // - deposit: amount of wei to first send into c so there is a balance to withdraw.
    // We cannot change msg.sender of this contract's calls, so we model two scenarios by using the public owner getter:
    // The invariant to assert: if c.owner() != address(this) then calling withdrawAll should NOT transfer c's entire balance to the given recipient.

    // Note: to observe transfer outcomes we compare address(c).balance before and after the withdrawAll call and assert
    // that when this contract is not owner, the full-balance transfer does not occur.

    receive() external payable {}

    function run(address payable recipient, uint256 deposit) public payable {
        // ensure this contract has enough ether to fund the deposit
        require(address(this).balance >= deposit, "insufficient balance for deposit");

        uint256 before = address(c).balance;

        // fund target contract c if deposit > 0
        if (deposit > 0) {
            // send deposit to c using its fallback
            (bool ok, ) = address(c).call{value: deposit}("");
            require(ok, "deposit failed");
        }

        uint256 funded = address(c).balance;
        // ensure there is something to withdraw for meaningful check
        require(funded > 0, "no funds in target");

        // Record recipient balance before withdrawal
        uint256 recipientBefore = recipient.balance;

        // Call withdrawAll as this contract (msg.sender == address(this))
        c.withdrawAll(recipient);

        uint256 recipientAfter = recipient.balance;
        uint256 after = address(c).balance;

        // If this contract is not owner, then withdrawAll on the original should have NO effect (it reverts);
        // in mutant it will succeed and transfer full balance. We express this as:
        // if c.owner() != address(this) then recipientAfter - recipientBefore < funded (i.e., full balance not transferred)
        // Use <= funded-1 to avoid issues with zero; but keep as a comparison avoiding constants-only.
        if (c.owner() != address(this)) {
            assert(recipientAfter - recipientBefore < funded);
        } else {
            // If this contract is owner, withdrawAll should have transferred the full funded amount.
            assert(recipientAfter - recipientBefore == funded);
        }
    }
}

