    // single public test function: attempt to withdraw and assert that the caller must be the owner
    function checkWithdrawAll(address caller, address recipient, uint256 seedValue) public payable {
        // seedValue is the amount of ether this test contract should forward when calling withdrawAll
        // ensure this contract has enough balance to forward when using call with value
        require(address(this).balance >= seedValue);

        // read owner from the target contract
        address owner = c.owner();

        // We'll perform the withdrawAll call from this contract (msg.sender == this contract)
        // So the general rule to check is: if this contract is not the owner, the call must revert (i.e., not succeed).
        // We detect success by performing a low-level call and observing its boolean return.

        // prepare calldata for withdrawAll(address)
        bytes memory payload = abi.encodeWithSignature("withdrawAll(address)", recipient);

        // perform call with value seedValue forwarded to c so transfer will have balance to send out
        (bool ok, ) = address(c).call{value: seedValue}(payload);

        // The rule: withdrawAll may only succeed when msg.sender equals owner.
        // Here msg.sender is this contract; assert that (ok) implies (this contract == owner)
        assert(!ok || address(this) == owner);
    }

    // Allow the test contract to receive ether so it can forward seedValue
    receive() external payable {}
}

